// Route every message by tenant, not by producer.
export function partitionFor(msg: Envelope): number {
  const key = msg.tenantId ?? msg.producer;
  return murmur3(key) % PARTITIONS;
}

queue.consume(async (msg) => {
  const handler = registry.get(msg.type);
  if (!handler) return msg.deadLetter("no-handler");
  await withDeadline(handler(msg), msg.budgetMs);
});
